import { createHash } from 'node:crypto';
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// Authorize only the inline preamble generated by the installed React plugin.
const refreshHash = createHash('sha256')
  .update(react.preambleCode.replace('__BASE__', '/'))
  .digest('base64');

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5175,
    headers: {
      'Content-Security-Policy': [
        "default-src 'self'",
        "script-src 'self' 'sha256-" + refreshHash + "'",
        "script-src-attr 'none'",
        "style-src 'self' 'unsafe-inline'",
        "img-src 'self' data:",
        "connect-src 'self' http://localhost:4000 ws://localhost:5175",
        "object-src 'none'",
        "base-uri 'self'",
      ].join('; '),
    },
  },
});
